// Ported from the Node app's Sequelize model VehicleMaintenance (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class VehicleMaintenanceConfiguration : IEntityTypeConfiguration<VehicleMaintenance>
{
    public void Configure(EntityTypeBuilder<VehicleMaintenance> builder)
    {
        builder.ToTable("vehicle_maintenance");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.VehicleId).HasColumnName("vehicle_id");
        builder.Property(e => e.ServiceDate).HasColumnName("service_date").HasColumnType("date");
        builder.Property(e => e.Description).HasColumnName("description").HasColumnType("nvarchar(255)").HasMaxLength(255).IsRequired();
        builder.Property(e => e.Cost).HasColumnName("cost").HasColumnType("decimal(10,2)").HasDefaultValueSql("0");
        builder.Property(e => e.NextDue).HasColumnName("next_due").HasColumnType("date");
        builder.HasOne(e => e.Vehicle).WithMany(p => p.VehicleMaintenances).HasForeignKey(e => e.VehicleId).OnDelete(DeleteBehavior.NoAction);
    }
}
